func TestZZVerifyTmp(t *testing.T) {
	cases := []struct {
		name     string
		balancer ProxyBalancer
	}{
		{"RandomBalancer", NewRandomBalancer(nil)},
		{"RoundRobinBalancer", NewRoundRobinBalancer(nil)},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			// 1) Next(nil) must return nil, not panic.
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("Next(nil) panicked: %v", r)
					}
				}()
				if got := tc.balancer.Next(nil); got != nil {
					t.Fatalf("Next(nil) = %v, want nil", got)
				}
			}()

			// 2) Serving a request through the proxy middleware must yield 503, not panic.
			e := echo.New()
			e.Use(Proxy(tc.balancer))
			rec := httptest.NewRecorder()
			req := httptest.NewRequest(http.MethodGet, "/", nil)
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("ServeHTTP panicked: %v", r)
					}
				}()
				e.ServeHTTP(rec, req)
			}()
			if rec.Code != http.StatusServiceUnavailable {
				t.Fatalf("rec.Code = %d, want %d", rec.Code, http.StatusServiceUnavailable)
			}
			t.Logf("%s: Next(nil)==nil and status=%d (503) OK", tc.name, rec.Code)
		})
	}
}

