// reference matcher following echo route syntax: static chars, :param (>=1 char up to next '/'), * (rest, may be empty)
func refMatch(pattern, path string) bool {
	i, j := 0, 0
	for i < len(pattern) {
		switch pattern[i] {
		case ':':
			// consume name
			for i < len(pattern) && pattern[i] != '/' {
				i++
			}
			// consume value
			start := j
			for j < len(path) && path[j] != '/' {
				j++
			}
			if j == start {
				return false
			}
		case '*':
			return true
		default:
			if j >= len(path) || path[j] != pattern[i] {
				return false
			}
			i++
			j++
		}
	}
	return j == len(path)
}

