func ipath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString("/" + string(rune('a'+rnd.Intn(4))))
	}
	if rnd.Intn(4) == 0 {
		sb.WriteString("/")
	}
	return sb.String()
}

func TestZZInst(t *testing.T) {
	rnd := rand.New(rand.NewSource(3))
	for iter := 0; iter < 200000; iter++ {
		nRoutes := 1 + rnd.Intn(4)
		e := New()
		r := e.router
		pats := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			p := ipattern(rnd)
			pats = append(pats, p)
			r.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		for i := 0; i < 6; i++ {
			p := ipath(rnd)
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Fatalf("PANIC routes=%v path=%q: %v", pats, p, rec)
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, p, c)
			}()
		}
	}
	fmt.Println("no instrumentation hit")
}
